SELECT 'printings' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.card_printings t WHERE id=ANY(ARRAY['1ec3e5ff-f0c2-4ff2-8423-9021a810f5b7']::uuid[]) UNION ALL SELECT 'variants',id::text,to_jsonb(t) FROM catalog.card_variants t WHERE printing_id=ANY(ARRAY['1ec3e5ff-f0c2-4ff2-8423-9021a810f5b7']::uuid[]) UNION ALL SELECT 'names',id::text,to_jsonb(t) FROM catalog.card_names t WHERE printing_id=ANY(ARRAY['1ec3e5ff-f0c2-4ff2-8423-9021a810f5b7']::uuid[]) OR variant_id=ANY(ARRAY['c1697767-547d-4c48-a774-ccb5357f07b4']::uuid[]) UNION ALL SELECT 'sets',id::text,to_jsonb(t) FROM catalog.sets t WHERE id=ANY(ARRAY['d832f428-8d51-4ac0-a3cf-a5d38bddb88d']::uuid[]) UNION ALL SELECT 'sources',id::text,to_jsonb(t) FROM ingest.sources t WHERE (code IN ('scrydex','pokellector','tcgcollector','pricecharting') OR lower(base_url) LIKE '%pokellector.com%' OR lower(base_url) LIKE '%tcgcollector.com%' OR lower(base_url) LIKE '%pricecharting.com%') UNION ALL SELECT 'assets',id::text,to_jsonb(t) FROM catalog.assets t WHERE printing_id=ANY(ARRAY['1ec3e5ff-f0c2-4ff2-8423-9021a810f5b7']::uuid[]) OR variant_id=ANY(ARRAY['c1697767-547d-4c48-a774-ccb5357f07b4']::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['d832f428-8d51-4ac0-a3cf-a5d38bddb88d']::uuid[])) UNION ALL SELECT 'links',catalogue_version_id::text||':'||asset_id::text,to_jsonb(t) FROM catalog.catalogue_version_assets t WHERE printing_id=ANY(ARRAY['1ec3e5ff-f0c2-4ff2-8423-9021a810f5b7']::uuid[]) OR variant_id=ANY(ARRAY['c1697767-547d-4c48-a774-ccb5357f07b4']::uuid[]) OR asset_id IN(SELECT id FROM catalog.assets WHERE printing_id=ANY(ARRAY['1ec3e5ff-f0c2-4ff2-8423-9021a810f5b7']::uuid[]) OR variant_id=ANY(ARRAY['c1697767-547d-4c48-a774-ccb5357f07b4']::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['d832f428-8d51-4ac0-a3cf-a5d38bddb88d']::uuid[]))) OR(printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['d832f428-8d51-4ac0-a3cf-a5d38bddb88d']::uuid[])) ORDER BY scope,identity;
